// Register/cycle MPU6050 motion input model. No DMP or auxiliary I2C master.
const HZ=16000000,clamp=n=>Math.max(-32768,Math.min(32767,Math.round(n))),hi=n=>(n>>8)&255,lo=n=>n&255;
export class MPU6050{
 constructor(){this.environment={temperature:25,ax:0,ay:0,az:1,gx:0,gy:0,gz:0};this.reset();}
 reset(cycle=0){this.r=new Uint8Array(128);this.r[0x6b]=0x40;this.r[0x75]=0x68;this.pointer=0;this.first=true;this.lastCycle=cycle;this.fifo=[];this.interrupt=0;this.pulseUntil=0;this.revision=0;this.unsupported=false;this.latched=null;}
 setEnvironment(p){this.environment=Object.fromEntries(Object.entries(this.environment).map(([k,v])=>[k,p?.[k]??({temperature:25,ax:0,ay:0,az:1,gx:0,gy:0,gz:0}[k])]));}
 get sleeping(){return !!(this.r[0x6b]&0x40);}
 get period(){const dlpf=this.r[0x1a]&7;return Math.ceil(HZ*(this.r[0x19]+1)/((dlpf===0||dlpf===7)?8000:1000));}
 sample(){const e=this.environment,acc=[16384,8192,4096,2048][(this.r[0x1c]>>3)&3],gyro=[131,65.5,32.8,16.4][(this.r[0x1b]>>3)&3],values=[e.ax*acc,e.ay*acc,e.az*acc,(e.temperature-36.53)*340,e.gx*gyro,e.gy*gyro,e.gz*gyro];for(let i=0;i<7;i++){let n=clamp(values[i]);const disabled=i<3&&(this.r[0x6c]&(1<<(5-i)))||i>=4&&(this.r[0x6c]&(1<<(6-i)))||i===3&&(this.r[0x6b]&8);if(disabled)n=0;this.r[0x3b+i*2]=hi(n);this.r[0x3c+i*2]=lo(n);}this.interrupt|=1;this.revision++;}
 fifoSample(){const b=this.r.slice(0x3b,0x49),mask=this.r[0x23],packet=[];if(mask&8)packet.push(...b.slice(0,6));if(mask&128)packet.push(...b.slice(6,8));for(let i=0;i<3;i++)if(mask&(64>>i))packet.push(...b.slice(8+i*2,10+i*2));if(this.fifo.length+packet.length>1024){this.interrupt|=16;return;}this.fifo.push(...packet);}
 tick(cycle){this.cycle=cycle;if(this.sleeping){this.lastCycle=cycle;return;}const count=Math.floor((cycle-this.lastCycle)/this.period);if(count>0){this.lastCycle+=count*this.period;this.sample();if(this.r[0x6a]&64)for(let i=0;i<Math.min(count,1025);i++)this.fifoSample();if(!(this.r[0x37]&32))this.pulseUntil=this.lastCycle+800;}}
 nextEvent(cycle){if(this.sleeping)return null;if(this.r[0x38]||this.r[0x6a]&64)return Math.max(cycle+1,Math.min(this.lastCycle+this.period,!(this.r[0x37]&32)&&this.pulseUntil>cycle?this.pulseUntil:Infinity));return null;}
 begin(write,cycle){this.tick(cycle);this.first=write;this.latched=this.r.slice();}
 write(b,cycle){this.tick(cycle);if(this.first){this.pointer=b&127;this.first=false;return true;}const a=this.pointer;if(a===0x6b&&b&128)this.reset(cycle);else if(a===0x6a){this.r[a]=b&0xf0;if(b&4)this.fifo=[];if(b&1){this.interrupt=0;this.r.fill(0,0x3b,0x49);}}else if(a===0x74){if(this.fifo.length<1024)this.fifo.push(b);else this.interrupt|=16;}else if(!((a>=0x3a&&a<=0x48)||a===0x72||a===0x73||a===0x75)){this.r[a]=b;if(a===0x6b||a===0x19||a===0x1a)this.lastCycle=cycle;}this.unsupported=!!(this.r[0x6a]&0xa0||this.r[0x23]&7||this.r[0x6b]&0x20||this.r[0x1c]&0xe0||this.r[0x1b]&0xe0);this.pointer=(a+1)&127;return true;}
 read(cycle){this.tick(cycle);const a=this.pointer;let b;if(a===0x3a)b=this.interrupt;else if(a===0x72)b=this.fifo.length>>8;else if(a===0x73)b=this.fifo.length&255;else if(a===0x74)b=this.fifo.shift()??0;else b=this.latched?.[a]??this.r[a];if(a!==0x74)this.pointer=(a+1)&127;if(a===0x3a||this.r[0x37]&16)this.interrupt=0;return b;}
 drivers(voltage,ground=0){const active=!this.sleeping&&!!(this.interrupt&this.r[0x38])&&((this.r[0x37]&32)||this.cycle<this.pulseUntil),high=(this.r[0x37]&128)?!active:active;if(this.r[0x37]&64&&high)return [];return [{pin:'INT',voltage:ground+(high?voltage:0),ohms:50}];}
 state(cycle){this.tick(cycle);return{...this.environment,sleeping:this.sleeping,accelRange:[2,4,8,16][(this.r[0x1c]>>3)&3],gyroRange:[250,500,1000,2000][(this.r[0x1b]>>3)&3],sampleHz:HZ/this.period,interrupt:this.interrupt,revision:this.revision,fifoBytes:this.fifo.length,unsupported:this.unsupported};}
}
